// Reads the failed run from the Error Trigger and decides: post an alert now, or only count a repeat.
// A repeat is the same workflow, the same node and the same message (ids, times and numbers of 4 or more digits ignored)
// within ALERT_REPEAT_WINDOW_MINUTES of the first alert. The repeat check posts one summary per window.
// ---- Text helpers ----
// Slack reads &, < and > as control characters (<!channel>, <url|label>), so anything that did not come
// from this workflow is escaped before it reaches Slack.
const slackEscape = (text) => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const oneLine = (text, max) => {
  const flat = String(text ?? '').replace(/\s+/g, ' ').trim();
  return flat.length > max ? flat.slice(0, max - 3) + '...' : flat;
};
function zoneOrNull(zone) {
  if (!zone) return null;
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: zone });
    return zone;
  } catch (e) {
    return null;
  }
}
function clockText(ms, zone) {
  return new Intl.DateTimeFormat('en-US', { timeZone: zone, month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(ms));
}
function durationText(ms) {
  if (ms < 60000) return `${Math.max(1, Math.round(ms / 1000))} s`;
  const minutes = Math.floor(ms / 60000);
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours < 48) return rest ? `${hours} h ${rest} min` : `${hours} h`;
  return `${Math.round(hours / 24)} days`;
}
const plural = (n, word, many) => `${n} ${n === 1 ? word : many || word + 's'}`;
const env = {
  slack: $env.SLACK_WEBHOOK_URL,
  window: $env.ALERT_REPEAT_WINDOW_MINUTES,
  zone: $env.TIMEZONE,
  editor: $env.N8N_EDITOR_URL,
};
const data = $input.first().json;
const now = Date.now();
const zone = zoneOrNull(String(env.zone || '').trim()) || 'UTC';
const windowRaw = String(env.window ?? '').trim();
let windowMinutes = windowRaw === '' ? 30 : Number(windowRaw);
if (!Number.isFinite(windowMinutes) || windowMinutes < 0) windowMinutes = 30;
const windowText = durationText(windowMinutes * 60000);

const workflow = data.workflow || {};
const execution = data.execution || null;
const trigger = data.trigger || null;
const error = (execution ? execution.error : trigger && trigger.error) || {};

// The node that failed. When the trigger itself fails there is no execution, only trigger.error.
const node = String((execution && execution.lastNodeExecuted) || (error.node && error.node.name) || (trigger ? 'the trigger' : 'unknown node'));

// The message. n8n cuts Code node errors at the last colon (for example "00Z [line 1]"), so the full text
// is taken from the first line of the stack when that line ends with the same words.
let message = String(error.message || (error.cause && error.cause.message) || error.name || 'No error message');
const stackLine = String(error.stack || '').split('\n')[0];
const fromStack = stackLine.match(/^[A-Za-z]*Error: (.+)$/);
const shortMessage = message.replace(/\s*\[line \d+\]$/, '');
if (fromStack && fromStack[1].length > shortMessage.length && fromStack[1].endsWith(shortMessage)) message = fromStack[1];
if (error.description && !message.includes(String(error.description))) message += ': ' + error.description;
if (error.httpCode && !/HTTP \d{3}/.test(message)) message += ` (HTTP ${error.httpCode})`;

// Repeats are grouped by a fingerprint that ignores ids, long numbers and timestamps,
// so "order 48213 failed" and "order 48214 failed" count as the same problem.
const normalized = message.toLowerCase()
  .replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/g, '<id>')
  .replace(/\d{4}-\d{2}-\d{2}[t ]\d{2}:\d{2}(:\d{2}(\.\d+)?)?(z|[+-]\d{2}:?\d{2})?/g, '<time>')
  .replace(/\b(?=[0-9a-z]*\d)(?=[0-9a-z]*[a-z])[0-9a-z]{12,}\b/g, '<id>')
  .replace(/\d{4,}/g, '#')
  .replace(/\s+/g, ' ').trim().slice(0, 400);
let hash = 2166136261;
for (const ch of `${node}\n${normalized}`) hash = Math.imul(hash ^ ch.codePointAt(0), 16777619) >>> 0;
const key = `${workflow.id || workflow.name || 'unknown'}:${hash.toString(16)}`;

// Links use N8N_EDITOR_URL when it is set. n8n's own execution.url is built from WEBHOOK_URL, which can be a
// different address than the editor (for example a public webhook domain that only serves /webhook paths).
const editorBase = String(env.editor || '').trim().replace(/\/+$/, '');
let url = '';
if (execution) url = editorBase && workflow.id && execution.id ? `${editorBase}/workflow/${workflow.id}/executions/${execution.id}` : String(execution.url || '');
else if (editorBase && workflow.id) url = `${editorBase}/workflow/${workflow.id}`;

const store = $getWorkflowStaticData('global');
store.alerts = store.alerts || {};
const alerts = store.alerts;
let entry = alerts[key];
let earlier = null;
if (entry && now >= entry.windowEnds) {
  // The window is over but the repeat check has not summed it up yet: carry its count into this alert.
  earlier = { count: entry.sent ? entry.count - entry.reported : entry.count, sent: entry.sent, firstAt: entry.firstAt, lastAt: entry.lastAt };
  delete alerts[key];
  entry = null;
}
let action;
if (!entry) {
  entry = alerts[key] = {
    workflowId: String(workflow.id || ''), workflowName: String(workflow.name || 'Unknown workflow'), node, message,
    firstAt: now, lastAt: now, windowEnds: now + windowMinutes * 60000, count: 1, reported: 0, sent: false, lastUrl: url,
  };
  action = 'alert';
} else {
  entry.count += 1;
  entry.lastAt = now;
  entry.message = message;
  if (url) entry.lastUrl = url;
  // Only post again if the first alert never reached Slack.
  action = entry.sent ? 'count' : 'alert';
}
// Keep the memory small: drop the oldest groups beyond 300.
const keys = Object.keys(alerts);
if (keys.length > 300) keys.sort((a, b) => alerts[a].lastAt - alerts[b].lastAt).slice(0, keys.length - 300).forEach((k) => delete alerts[k]);

const lines = [`:rotating_light: *${slackEscape(entry.workflowName)}* failed at *${slackEscape(node)}*`, slackEscape(oneLine(message, 700))];
if (entry.count > 1) lines.push(`Failed ${entry.count} times since ${clockText(entry.firstAt, zone)} (${zone}). The first alert could not be posted.`);
if (earlier && earlier.count > 0) {
  // Those failures can be much older than the window (for example while Slack was down), so give their times.
  if (earlier.sent) lines.push(`It also failed ${plural(earlier.count, 'more time')} after the last alert, the latest at ${clockText(earlier.lastAt, zone)} (${zone}), and that was not summed up yet.`);
  else if (earlier.count === 1) lines.push(`It also failed once before, at ${clockText(earlier.firstAt, zone)} (${zone}), and that alert could not be posted.`);
  else lines.push(`It also failed ${earlier.count} times before, between ${clockText(earlier.firstAt, zone)} and ${clockText(earlier.lastAt, zone)} (${zone}), and that alert could not be posted.`);
}
if (execution && execution.retryOf) lines.push(`This run was a retry of execution ${slackEscape(execution.retryOf)}.`);
lines.push(url || (trigger ? 'The trigger failed before a run started, so there is no execution to open.' : 'No link: n8n did not save this run.'));
if (windowMinutes > 0 && entry.count === 1) lines.push(`Repeats of this error in the next ${windowText} are counted and summed up in one follow-up.`);

if (!String(env.slack || '').trim()) action = 'no_slack';
return [{ json: { action, key, text: lines.join('\n'), workflowName: entry.workflowName, node, message, count: entry.count, executionId: execution ? String(execution.id || '') : '' } }];

// The alert reached Slack: later repeats in this window are only counted.
const item = $('Read Error').first().json;
const store = $getWorkflowStaticData('global');
const entry = (store.alerts || {})[item.key];
if (entry) {
  entry.sent = true;
  entry.reported = entry.count;
}
return [{ json: { posted: true, key: item.key, count: item.count } }];

// Runs on a schedule. For every error group whose window has ended:
// - repeats after the first alert: one summary with the count and the latest run,
// - first alert never posted (Slack was down): post it now, with the count,
// - nothing more to say: forget the group.
// Groups are only removed after Slack accepted the message (Mark Summary Sent).
// ---- Text helpers ----
// Slack reads &, < and > as control characters (<!channel>, <url|label>), so anything that did not come
// from this workflow is escaped before it reaches Slack.
const slackEscape = (text) => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const oneLine = (text, max) => {
  const flat = String(text ?? '').replace(/\s+/g, ' ').trim();
  return flat.length > max ? flat.slice(0, max - 3) + '...' : flat;
};
function zoneOrNull(zone) {
  if (!zone) return null;
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: zone });
    return zone;
  } catch (e) {
    return null;
  }
}
function clockText(ms, zone) {
  return new Intl.DateTimeFormat('en-US', { timeZone: zone, month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(ms));
}
function durationText(ms) {
  if (ms < 60000) return `${Math.max(1, Math.round(ms / 1000))} s`;
  const minutes = Math.floor(ms / 60000);
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours < 48) return rest ? `${hours} h ${rest} min` : `${hours} h`;
  return `${Math.round(hours / 24)} days`;
}
const plural = (n, word, many) => `${n} ${n === 1 ? word : many || word + 's'}`;
const env = { slack: $env.SLACK_WEBHOOK_URL, zone: $env.TIMEZONE };
const zone = zoneOrNull(String(env.zone || '').trim()) || 'UTC';
const store = $getWorkflowStaticData('global');
const alerts = store.alerts || {};
const now = Date.now();
const out = [];
for (const [key, entry] of Object.entries(alerts)) {
  if (now < entry.windowEnds) continue;
  const name = slackEscape(entry.workflowName);
  const node = slackEscape(entry.node);
  const message = slackEscape(oneLine(entry.message, 700));
  const day = (ms) => new Intl.DateTimeFormat('en-US', { timeZone: zone, month: 'short', day: 'numeric' }).format(new Date(ms));
  const time = (ms) => new Intl.DateTimeFormat('en-US', { timeZone: zone, hour: 'numeric', minute: '2-digit' }).format(new Date(ms));
  const span = day(entry.firstAt) === day(entry.lastAt)
    ? `between ${time(entry.firstAt)} and ${time(entry.lastAt)} on ${day(entry.firstAt)} (${zone})`
    : `between ${clockText(entry.firstAt, zone)} and ${clockText(entry.lastAt, zone)} (${zone})`;
  if (!entry.sent) {
    out.push({ key, kind: 'late alert', count: entry.count, text: [
      `:rotating_light: *${name}* failed at *${node}*`,
      message,
      entry.count === 1
        ? `Failed once, at ${clockText(entry.firstAt, zone)} (${zone}). The alert could not be posted when it happened.`
        : `Failed ${entry.count} times ${span}. The alert could not be posted when it happened.`,
      `Latest run: ${entry.lastUrl || 'no link'}`,
    ].join('\n') });
    continue;
  }
  const more = entry.count - entry.reported;
  if (more <= 0) {
    delete alerts[key];
    continue;
  }
  out.push({ key, kind: 'summary', count: entry.count, more, text: [
    `:repeat: *${name}* failed at *${node}* ${plural(more, 'more time')} after the first alert, ${entry.count} in total ${span}.`,
    message,
    `Latest run: ${entry.lastUrl || 'no link'}`,
  ].join('\n') });
}
if (!String(env.slack || '').trim()) {
  // Nowhere to post: forget the finished windows instead of piling them up.
  out.forEach((o) => delete alerts[o.key]);
  return [];
}
return out.map((json) => ({ json }));

// Slack accepted this summary: forget its group. The loop sends one summary per Slack call, so a refused summary is
// retried on its own and never re-posts the others. If one is still refused, the run stops at Stop: Summary Failed
// and the groups not posted yet stay for the next check.
const store = $getWorkflowStaticData('global');
const alerts = store.alerts || {};
const source = $('Loop: Summaries').first().json;
delete alerts[source.key];
return [{ json: { posted: source.key, kind: source.kind } }];
